package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaNlDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_ma_amiltu" to DuaText("Toevlucht voor het kwaad van mijn daden", "O Allah, ik zoek toevlucht bij U tegen het kwaad van wat ik heb gedaan en tegen het kwaad van wat ik niet heb gedaan.", "Een dua van de Profeet ﷺ, volgens Aisha (RA).", "Bescherming tegen de gevolgen van zowel wat er is gedaan als wat ongedaan is gelaten."),
        "dua_jahdil_bala" to DuaText("Toevlucht voor zware beproevingen", "O Allah, ik zoek mijn toevlucht bij U tegen zware beproevingen, tegen het overvallen worden door ellende, tegen een kwaadaardig besluit en tegen het leedvermaak van vijanden.", "Toevlucht voor zware beproevingen en het leedvermaak van vijanden.", "De Profeet ﷺ zocht zijn toevlucht tegen deze vier dingen."),
        "dua_fitnat_ghina_faqr" to DuaText("Toevlucht voor de beproevingen van rijkdom en armoede", "O Allah, ik zoek toevlucht bij U tegen luiheid en ouderdom, tegen zonde en schulden, tegen de beproeving en bestraffing van het graf, tegen de beproeving en bestraffing van het Vuur, tegen het kwaad van de beproeving van rijkdom, en tegen de beproeving van armoede.", "Toevlucht voor de beproevingen van het graf, de hel, rijkdom en armoede (onderdeel van de dua).", "Een uitgebreid dua van toevlucht tegen de Profeet ﷺ."),
        "dua_kufr_faqr" to DuaText("Toevlucht voor ongeloof en armoede", "O Allah, ik zoek toevlucht bij U tegen ongeloof en armoede, en ik zoek toevlucht bij U tegen de bestraffing van het graf. Er is geen god behalve Jij.", "Drie keer 's ochtends en 's avonds.", "Abu Bakrah (RA) hoorde de Profeet ﷺ dit zeggen."),
        "dua_sharri_sami" to DuaText("Toevlucht voor het kwaad van mijn zintuigen", "O Allah, ik zoek toevlucht bij U tegen het kwaad van mijn gehoor, het kwaad van mijn zicht, het kwaad van mijn tong, het kwaad van mijn hart en het kwaad van mijn verlangen.", "Onderwezen aan Shakal ibn Humayd (RA).", "Een dua om de ledematen en het zelf tegen zonde te beschermen."),
        "dua_hadm_gharaq" to DuaText("Toevlucht tegen plotselinge dood en ongevallen", "O Allah, ik zoek toevlucht bij U tegen verpletterd worden (door een gebouw), tegen vallen van een hoogte, tegen verdrinking, verbranding en ouderdom; van Shaytan die mij op een dwaalspoor bracht op het moment van overlijden, van sterven terwijl ik van Uw pad vlucht, en van sterven aan een (giftige) steek.", "Toevlucht voor ongelukken en een slechte dood.", "Een dua van toevlucht tegen de Profeet ﷺ."),
        "dua_ju_khiyanah" to DuaText("Toevlucht tegen honger en verraad", "O Allah, ik zoek toevlucht bij U tegen honger, want het is een slechte metgezel, en ik zoek toevlucht bij U tegen verraad, want het is een slechte vertrouweling.", "Toevlucht voor honger en verraad.", "Een dua van toevlucht tegen de Profeet ﷺ."),
        "dua_huda_tuqa" to DuaText("Leiding, vroomheid, kuisheid en toereikendheid", "O Allah, ik vraag U om leiding, vroomheid, kuisheid en zelfvoorziening.", "Een korte, uitgebreide dua van de Profeet ﷺ.", "Vier fundamentele zegeningen van religie en deze wereld."),
        "dua_aslih_li_dini" to DuaText("Corrigeer mijn religie, wereld en hiernamaals", "O Allah, breng mijn religie in orde, die de bescherming is van al mijn zaken; mijn wereldse leven, waarin mijn levensonderhoud ligt, rechtzetten; en zet mijn Hiernamaals in orde, waarnaar ik zal terugkeren. Maak het leven voor mij een vermeerdering in al het goede, en maak de dood voor mij een verlichting van al het kwaad.", "Hervormende religie, deze wereld en het Hiernamaals – alle drie.", "Een uitgebreide dua van de Profeet ﷺ."),
        "dua_musarrifal_qulub" to DuaText("Richt ons hart op uw gehoorzaamheid", "O Allah, hartenherder, keer onze harten naar Uw gehoorzaamheid.", "Een dua om het hart standvastig te houden in gehoorzaamheid.", "De harten van alle mensen liggen tussen de twee vingers van de Meest Barmhartige."),
        "dua_jannah_nar" to DuaText("Vragen om Jannah, toevlucht tegen vuur", "O Allah, ik vraag U om het Paradijs en ik zoek toevlucht bij U tegen het Vuur.", "Na de tashahhud of op welk moment dan ook.", "De Profeet ﷺ zei: ook onze dua's draaien hierom."),
        "dua_khayri_kullih" to DuaText("Alles goed, nu en later", "O Allah, ik vraag U om al het goede – het onmiddellijke en het uitgestelde, wat ik weet en wat ik niet weet – en ik zoek toevlucht bij U tegen al het kwaad – het onmiddellijke en het uitgestelde, wat ik weet en wat ik niet weet. O Allah, ik vraag U om het Paradijs en voor welke woorden en daden mij ook dichtbij brengen, en ik zoek toevlucht bij U tegen het Vuur en tegen welke woorden en daden mij ook dichtbij brengen.", "De Profeet ﷺ onderwees deze uitgebreide dua aan Aisha (RA) (onderdeel van de dua).", "Een dua die al het goede verzamelt."),
        "dua_ihdini_saddidni" to DuaText("Leid mij en houd mij rechtop", "O Allah, leid mij en houd mij op de goede koers.", "De Profeet ﷺ leerde het aan Ali (RA).", "Beschouw leiding als geleid worden over een weg, en over sadad als de rechtheid van een pijl."),
        "dua_hubbaka" to DuaText("Vragen om de liefde van Allah", "O Allah, ik vraag U om Uw liefde, de liefde van degenen die van U houden, en daden die mij tot Uw liefde brengen. O Allah, maak Uw liefde mij dierbaarder dan mijzelf, mijn familie en koud water.", "De dua van Dawud (AS) overgeleverd door de Profeet ﷺ.", "De liefde voor Allah is de grootste rijkdom."),
        "dua_filal_khayrat" to DuaText("Goed doen en kwaad achterwege laten", "O Allah, ik vraag U om mij in staat te stellen goede daden te verrichten, slechte daden achterwege te laten en van de armen te houden, en dat U mij vergeeft en genade met mij heeft. En als U een beproeving voor een volk plant, neem mij dan mee zonder berecht te worden. Ik vraag U om Uw liefde, de liefde van degenen die van U houden, en de liefde voor daden die mij dichtbij Uw liefde brengen.", "Allah leerde deze du aan de Profeet ﷺ in een droom.", "De Profeet ﷺ zei: het is waar, dus leer het en onderwijs het."),
        "dua_bi_ilmikal_ghayb" to DuaText("Laat mij leven terwijl het leven goed is", "O Allah, bij Uw kennis van het ongeziene en Uw macht over de schepping – houd mij in leven zolang U weet dat het leven beter voor mij is, en neem mij mee als U weet dat de dood beter voor mij is. O Allah, ik vraag U om angst voor U zowel privé als in het openbaar, om het woord van de waarheid in tevredenheid en in woede, en om gematigdheid in armoede en in rijkdom.", "Het gebedsdua van Ammar ibn Yasir (RA) (openingsgedeelte).", "De Profeet ﷺ maakte deze dua in gebed."),
        "dua_ism_azam_mannan" to DuaText("Ism-e-Azam: Al-Mannan", "O Allah, ik vraag U, want aan U behoort alle lof; er is geen god behalve Jij, de Schenker van gunsten, Schepper van de hemel en de aarde. O Bezitter van Majesteit en Eer, O Altijdlevende, O Onderhouder!", "De Profeet ﷺ zei dat deze man dua deed met de grootste naam van Allah.", "Een dua gemaakt met deze Naam wordt beantwoord."),
        "dua_ism_azam_ahad_samad" to DuaText("Ism-e-Azam: Al-Ahad As-Samad", "O Allah, ik vraag U, want ik getuig dat U Allah bent; er is geen god behalve Jij, de Ene, de Zelfvoorzienende, die noch verwekt, noch geboren wordt, en er is niemand die met Hem te vergelijken is.", "De Profeet ﷺ zei dat deze man Allah bij Zijn grootste Naam vroeg.", "Als Hij erom gevraagd wordt, geeft Hij; wanneer Hij erdoor wordt geroepen, antwoordt Hij."),
        "dua_thabbitni_hadiyan" to DuaText("Maak mij standvastig, geleid en een gids", "O Allah, maak mij standvastig en maak mij iemand die leidt en geleid wordt.", "De Profeet ﷺ maakte deze dua voor Jarir (RA) (zeg voor jezelf 'thabbitni').", "De originele dua voor Jarir (RA) gebruikt de woorden 'thabbit-hu'."),
        "dua_rabbighfir_tub_alayya" to DuaText("Vergeef mij en aanvaard mijn berouw", "Mijn Heer, vergeef mij en aanvaard mijn berouw. U bent inderdaad de Acceptant van berouw, de Barmhartige.", "Honderd keer in één keer – de praktijk van de Profeet ﷺ.", "De metgezellen telden dat de Profeet ﷺ het honderd keer in één keer zei."),
        "dua_rafiq_ala" to DuaText("Dua van de stervende persoon", "O Allah, vergeef mij, heb genade met mij en sluit mij aan bij de Hoogste Metgezel.", "De laatste dua van de Profeet ﷺ – die de zieke voor zichzelf mag zeggen.", "De Profeet ﷺ maakte deze dua op het moment van zijn overlijden."),
        "dua_la_bas_tahur" to DuaText("De zieken troosten: zuivering", "Geen kwaad; het is een zuivering (van zonden), als Allah het wil.", "Om de zieken te troosten tijdens hun bezoek.", "De Profeet ﷺ zei dit toen hij de zieken bezocht."),
        "dua_talqeen" to DuaText("Talqeen voor de stervenden", "Niemand heeft het recht om aanbeden te worden behalve Allah.", "Reciteer de kalimah in de buurt van een stervende persoon (dwing hem niet om het te zeggen).", "Wie zijn laatste woorden 'La ilaha illallah' zijn, zal het Paradijs betreden (Abu Dawud 3116)."),
        "dua_ahyini_ma_kanat" to DuaText("In plaats van verlangen naar de dood", "O Allah, houd mij in leven zolang het leven beter voor mij is, en neem mij mee als de dood beter voor mij is.", "In plaats van te verlangen naar de dood in ontberingen.", "De Profeet ﷺ verbood het verlangen naar de dood en leerde dit in plaats daarvan."),
        "dua_for_one_i_cursed" to DuaText("Voor iemand die ik pijn heb gedaan met woorden", "O Allah, elke gelovige die ik heb beledigd, maak dat voor hem een ​​middel om dichter bij U te komen op de Dag der Opstanding.", "Voor iemand met wie je boos hebt gesproken.", "Een dua van de Profeet ﷺ."),
        "dua_praising_someone" to DuaText("Als je iemand prijst", "Ik beschouw die en die als deze, en Allah is zijn Rekener, en ik sta niet in voor de zuiverheid van iemand tegenover Allah.", "Als je iemand prijst, in plaats van te overdrijven.", "De Profeet ﷺ onderwees deze etiquette van lof."),
        "dua_being_praised" to DuaText("Wanneer je geprezen wordt", "O Allah, houd mij niet ter verantwoording voor wat zij zeggen, en vergeef mij voor wat zij niet weten.", "Wanneer je jezelf geprezen hoort worden – de praktijk van een metgezel (RA).", "Een manier om arrogantie te vermijden als je wordt geprezen."),
        "dua_non_muslim_sneezes" to DuaText("Wanneer een niet-moslim niest", "Moge Allah u leiden en uw zaken rechtzetten.", "Wanneer een niet-moslim niest en 'Alhamdulillah' zegt.", "Joden niesden in de buurt van de Profeet ﷺ in de hoop dat hij 'Yarhamukallah' zou zeggen, en hij zou dit zeggen."),
        "dua_reply_ahl_kitab_salam" to DuaText("Reagerend op Salam van Mensen van het Boek", "En op jou.", "Wanneer de Mensen van het Boek begroeten met salam.", "De instructie van de Profeet ﷺ."),
        "dua_fasting_invited" to DuaText("Wanneer u wordt uitgenodigd tijdens het vasten", "Ik ben aan het vasten.", "Wanneer u wordt uitgenodigd tijdens het vasten, of wanneer iemand ruzie met u maakt.", "Als de vastende een uitnodiging accepteert, moet hij voor de gastheer bidden."),
        "dua_for_who_gave_drink" to DuaText("Voor wie mij te eten gaf", "O Allah, voed degene die mij te eten heeft gegeven en geef te drinken aan degene die mij te drinken heeft gegeven.", "Voor degene die je eten of drinken geeft.", "De Profeet ﷺ maakte deze dua voor al-Miqdad (RA)."),
        "dua_eid_greeting" to DuaText("Eid-groet", "Moge Allah (goede daden) van ons en van jullie accepteren.", "Voor elkaar op de dag van Eid – de praktijk van de nobele metgezellen (RA).", "De metgezellen zeiden dit toen ze elkaar ontmoetten op Eid."),
        "dua_wedding_night" to DuaText("Voor de bruid na Nikah", "O Allah, ik vraag U om het goede van haar en het goede van de natuur waarmee U haar hebt geschapen, en ik zoek toevlucht bij U tegen haar kwaad en het kwade van de natuur waarmee U haar heeft geschapen.", "Na de nikah plaats je de hand op het voorhoofd van de vrouw.", "De leer van de Profeet ﷺ: zegen in het huwelijk."),
        "dua_istisqa_ibadak" to DuaText("Geef uw bedienden en dieren water", "O Allah, geef water aan Uw dienaren en Uw dieren, verspreid Uw genade en geef leven aan Uw dode land.", "Om regen vragen (istisqa).", "De Profeet ﷺ maakte deze dua voor regen."),
        "dua_seeing_clouds" to DuaText("Donkere wolken zien", "O Allah, ik zoek toevlucht bij U tegen het kwaad ervan.", "Bij het zien van donkere wolken in de lucht; als het regent, zeg dan 'Allahumma Sayyiban Nafi'a'.", "Bij het zien van wolken verliet de Profeet ﷺ waar hij mee bezig was en maakte deze dua."),
        "dua_jamarat" to DuaText("Het stenigen van de Jamarat", "Allah is de Grootste.", "Met elke gegooide kiezelsteen.", "De Profeet ﷺ zei takbir met elke kiezelsteen, en na de eerste en tweede jamrah keek hij naar de Qiblah en maakte een lange dua."),
        "dua_rabbi_ainni" to DuaText("Mijn Heer, help mij en niet tegen mij", "Mijn Heer, help mij en help anderen niet tegen mij, schenk mij de overwinning en schenk anderen geen overwinning over mij, maak plannen voor mij en maak geen plannen tegen mij, leid mij en maak leiding gemakkelijk voor mij, en help mij tegen wie mij onrecht aandoet.", "Een uitgebreide du van de Profeet ﷺ (openingsdeel).", "Een dua die alle hulp in religie en deze wereld verzamelt."),
        "dua_ati_nafsi_taqwaha" to DuaText("Geef mijn ziel zijn Taqwa", "O Allah, schenk mijn ziel haar vroomheid en zuiver haar, want U bent de beste om haar te zuiveren. Jij bent de Bewaker en de Meester ervan.", "Voor het hervormen en zuiveren van het zelf.", "De Profeet ﷺ maakte deze dua."),
        "dua_iqsim_lana_khashyatik" to DuaText("Geef ons zoveel angst voor u", "O Allah, geef ons genoeg angst voor U om tussen ons in te komen en U ongehoorzaam te zijn, genoeg gehoorzaamheid om ons naar Uw Paradijs te brengen, en genoeg zekerheid om de rampen van deze wereld gemakkelijk voor ons te maken. Laten we genieten van ons gehoor, ons zicht en onze kracht, zolang U ons in leven houdt en ervoor zorgt dat ze langer meegaan. Neem wraak op degenen die ons onrecht hebben aangedaan, help ons tegen onze vijanden, laat onze rampspoed niet in onze religie liggen, maak deze wereld niet tot onze grootste zorg of tot de grens van onze kennis, en stel niet degenen over ons heen die ons geen genade willen tonen.", "Wanneer hij opstond uit een bijeenkomst, stond de Profeet ﷺ zelden op zonder deze dua te maken.", "Een alomvattende dua voor het welzijn van religie, deze wereld en het Hiernamaals."),
        "dua_infani_bima_allamtani" to DuaText("Doe mij voordeel met wat je mij hebt geleerd", "O Allah, doe mij voordeel met wat U mij heeft geleerd, leer mij wat mij ten goede zal komen, en vergroot mij in kennis.", "Tijdens het zoeken naar kennis of vóór het studeren.", "Een dua voor nuttige kennis en het ernaar handelen."),
    )
}
